// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/health", wrapper.GetHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/debug", wrapper.GetDebug)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/blogs", wrapper.ListBlogs)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/blogs", wrapper.CreateBlog)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/blogs/{slug}", wrapper.DeleteBlog)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/blogs/{slug}", wrapper.GetBlog)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/blogs/{slug}", wrapper.UpdateBlog)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/blogs/{slug}/related", wrapper.RelatedBlogs)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/blogs/{slug}/chat", wrapper.DeleteChat)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/blogs/{slug}/chat", wrapper.GetChat)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/blogs/{slug}/chat", wrapper.SendChatMessage)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/blogs/{slug}/comments", wrapper.ListComments)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/blogs/{slug}/comments", wrapper.CreateComment)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/blogs/{slug}/comments/{id}", wrapper.DeleteComment)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/blogs/{slug}/comments/{id}/moderation", wrapper.ApproveComment)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/blogs/{slug}/reactions", wrapper.GetReactions)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/blogs/{slug}/reactions/{emoji}", wrapper.DeleteReaction)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/blogs/{slug}/reactions/{emoji}", wrapper.PutReaction)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/blogs/{slug}/comments/{id}/reactions/{emoji}", wrapper.DeleteCommentReaction)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/blogs/{slug}/comments/{id}/reactions/{emoji}", wrapper.PutCommentReaction)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/users/me", wrapper.DeleteUser)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/users/me", wrapper.GetCurrentUser)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/users/me", wrapper.PutUser)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/users/{username}", wrapper.GetUser)

	return m
}

